}

/**
 * Aggregate a deterministic reliability fixture.  Only complete cases (all k
 * trials present and terminal) are included in pass denominators; incomplete
 * cases are retained as evidence and never silently converted into failures.
 */
export function aggregateReliability(fixture) {
  const k = Number(fixture?.k);
  const minCases = Number(fixture?.minCases);
  const cases = Array.isArray(fixture?.cases) ? fixture.cases : [];
  if (!Number.isInteger(k) || k < 1) throw new Error('reliability fixture requires a positive integer k');
  if (!Number.isInteger(minCases) || minCases < 1) throw new Error('reliability fixture requires a positive integer minCases');

  const complete = [];
  const incomplete = [];
  for (const item of cases) {
    const trials = Array.isArray(item.trials) ? item.trials : [];
    const statuses = trials.map(statusOf);
    const missingTrials = k - trials.length;
    const isComplete = trials.length === k && statuses.every((s) => s !== 'missing' && s !== 'timeout' && s !== 'crash' && s !== 'skip');
    const record = {
      id: String(item.id),
      kind: item.kind ?? 'case',
      safety: Boolean(item.safety),
      anchor: item.anchor ?? null,
      trials: statuses,
      incomplete: !isComplete,
      incompleteReasons: [
        ...(missingTrials > 0 ? [`missing-${missingTrials}`] : []),
        ...[...new Set(statuses.filter((s) => ['missing', 'timeout', 'crash', 'skip'].includes(s)))],
      ],
    };
    (isComplete ? complete : incomplete).push(record);
  }

  const completeCases = complete.length;
  const passK = complete.filter((c) => c.trials.every(isPass)).length;
  const passAtK = complete.filter((c) => c.trials.some(isPass)).length;
  const flaky = complete.filter((c) => c.trials[0] === 'fail' && c.trials.slice(1).some(isPass)).length;
  const flakyCases = complete.filter((c) => c.trials[0] === 'fail' && c.trials.slice(1).some(isPass)).map((c) => c.id);
  const safetyCases = complete.filter((c) => c.safety);
  const safetyFlake = safetyCases.filter((c) => c.trials[0] === 'fail' && c.trials.slice(1).some(isPass)).length;
  const safetySkip = safetyCases.filter((c) => c.trials.some((s) => s === 'skip')).length;
  const positives = complete.filter((c) => c.anchor === 'positive');
  const negatives = complete.filter((c) => c.anchor === 'negative');
  const positiveViolations = positives.filter((c) => !c.trials.every(isPass)).map((c) => c.id);
  const negativeViolations = negatives.filter((c) => !c.trials.every(isReject)).map((c) => c.id);

  const reasons = [];
  if (completeCases < minCases) reasons.push(`complete-case-count ${completeCases} < ${minCases}`);
  if (positiveViolations.length) reasons.push(`positive-anchor-violations: ${positiveViolations.join(',')}`);
  if (negativeViolations.length) reasons.push(`negative-anchor-violations: ${negativeViolations.join(',')}`);
  if (safetySkip) reasons.push(`safety-skip: ${safetySkip}`);
  if (safetyFlake) reasons.push(`safety-flake: ${safetyFlake}`);
  const flakeRate = ratio(flaky, completeCases);
  if (fixture.flakeThreshold !== undefined && flakeRate > Number(fixture.flakeThreshold)) reasons.push(`flake-rate ${flakeRate} > ${fixture.flakeThreshold}`);
  if (fixture.passKThreshold !== undefined && ratio(passK, completeCases) < Number(fixture.passKThreshold)) reasons.push('pass^k below threshold');

  let gate = 'pass';
  if (completeCases < minCases) gate = 'insufficient-sample';
  if (positiveViolations.length || negativeViolations.length || safetySkip || safetyFlake || reasons.some((r) => r.startsWith('flake-rate') || r === 'pass^k below threshold')) gate = 'fail';

  return {
    k,
    minCases,
    deterministicOracle: true,
    rawCaseCount: cases.length,
    completeCaseCount: completeCases,
    incompleteCaseCount: incomplete.length,
    passK: { numerator: passK, denominator: completeCases, rate: round(ratio(passK, completeCases)) },
    passAtK: { numerator: passAtK, denominator: completeCases, rate: round(ratio(passAtK, completeCases)) },
    flake: { numerator: flaky, denominator: completeCases, rate: round(flakeRate), caseIds: flakyCases },
    missing: incomplete.map((c) => ({ id: c.id, reasons: c.incompleteReasons, trials: c.trials })),
    safety: { cases: safetyCases.length, skips: safetySkip, flakes: safetyFlake },
    anchors: { positive: { cases: positives.length, violations: positiveViolations }, negative: { cases: negatives.length, violations: negativeViolations } },
    gate,
    reasons,
    cases: complete.concat(incomplete),
  };
}

export default aggregateReliability;
